import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import type { Row } from './jobs.ts';

const db = openDatabase();
let stopping = false;
const nowIso = () => new Date().toISOString();
function heartbeat(): void { db.prepare('INSERT INTO worker_heartbeat(singleton,at) VALUES(1,?) ON CONFLICT(singleton) DO UPDATE SET at=excluded.at').run(Date.now()); }
heartbeat();
const beatTimer = setInterval(() => { try { heartbeat(); } catch (e) { console.error('heartbeat failed', e); } }, 500);
// Interrupted attempts below the limit are retried as a fresh attempt. The final attempt
// is kept running and resumed without increasing its attempt counter.
const interrupted = db.prepare("SELECT seq,attempts FROM jobs WHERE status='running' ORDER BY seq").all() as Row[];
let resumeFinalSeq: number | undefined;
for (const row of interrupted) {
  const seq = Number(row.seq);
  if (Number(row.attempts) >= 3 && resumeFinalSeq === undefined) {
    db.prepare("UPDATE jobs SET completed=0,output=NULL,error=NULL,updated_at=? WHERE seq=?").run(nowIso(),seq);
    resumeFinalSeq = seq;
  } else {
    db.prepare("UPDATE jobs SET status='queued',completed=0,output=NULL,error=NULL,available_at=0,updated_at=? WHERE seq=?").run(nowIso(),seq);
  }
}

function claim(): Row | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (resumeFinalSeq !== undefined) {
      const row = db.prepare("SELECT * FROM jobs WHERE seq=? AND status='running'").get(resumeFinalSeq) as Row|undefined;
      resumeFinalSeq = undefined;
      if (row) { db.exec('COMMIT'); return row; }
    }
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY seq LIMIT 1").get(Date.now()) as Row|undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const timestamp = nowIso();
    db.prepare("UPDATE jobs SET status='running',attempts=attempts+1,completed=0,output=NULL,error=NULL,updated_at=? WHERE seq=? AND status='queued'").run(timestamp,row.seq);
    const claimed = db.prepare('SELECT * FROM jobs WHERE seq=?').get(row.seq) as Row;
    db.exec('COMMIT'); return claimed;
  } catch (e) { try { db.exec('ROLLBACK'); } catch {} throw e; }
}
function updateStep(seq: number, completed: number, output?: string): void {
  const timestamp = nowIso();
  if (output !== undefined) db.prepare("UPDATE jobs SET completed=?,status='completed',output=?,error=NULL,updated_at=? WHERE seq=? AND status='running'").run(completed,output,timestamp,seq);
  else db.prepare("UPDATE jobs SET completed=?,updated_at=? WHERE seq=? AND status='running'").run(completed,timestamp,seq);
}
function failOrRetry(seq: number, attempts: number): void {
  const timestamp = nowIso();
  if (attempts >= 3) db.prepare("UPDATE jobs SET status='failed',completed=0,output=NULL,error='transient failure',updated_at=? WHERE seq=? AND status='running'").run(timestamp,seq);
  else db.prepare("UPDATE jobs SET status='queued',completed=0,output=NULL,error=NULL,available_at=?,updated_at=? WHERE seq=? AND status='running'").run(Date.now()+500,timestamp,seq);
}
async function processJob(row: Row): Promise<void> {
  const seq=Number(row.seq), attempts=Number(row.attempts), steps=Number(row.steps), failAttempts=Number(row.fail_attempts), input=String(row.input);
  for (let step=1; step<=steps; step++) {
    await sleep(100);
    if (step===1 && attempts<=failAttempts) { failOrRetry(seq,attempts); return; }
    updateStep(seq,step,step===steps ? input.toUpperCase() : undefined);
  }
}
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping=true; });
console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const job = claim();
    if (job) { await processJob(job); continue; }
    await sleep(100);
  }
} finally {
  clearInterval(beatTimer);
  db.prepare('DELETE FROM worker_heartbeat WHERE singleton=1').run();
  db.close();
}
